    P("1913-01-23", "1918-11-01", "Ottoman Empire under CUP (Three Pashas)", gov="one_party_state", capital="Constantinople (Istanbul)",
      removal=["coup", "foreign_occupation", "assassination"],
      succession="Raid on the Sublime Porte (23 Jan 1913) brought the Committee of Union and Progress to power; from mid-1913 effective rule by Talat (Interior), Enver (War) and Cemal (Navy) Pashas; Sultan a figurehead.",
      notes="Game: removal only by coup, military defeat or collapse (the triumvirs fled 2 Nov 1918)."),
    P("1918-11-01", "1922-11-01", "Ottoman Empire under Allied occupation (Istanbul government)", gov="colonial_or_occupied", capital="Constantinople (Istanbul) - occupied by the Allies (formally 16 Mar 1920)",
      removal=["royal_dismissal", "foreign_occupation", "revolution"],
      succession="Sultan Mehmed VI governed through grand viziers acceptable to the Allies; parliament dissolved Apr 1920. Overlaps with the rival Ankara government from Apr 1920.",
      notes="Sultanate abolished 1 Nov 1922 by the Ankara Grand National Assembly; the last grand vizier resigned 4 Nov 1922."),
    P("1920-04-23", "1923-10-29", "Government of the Grand National Assembly (Ankara)", gov="revolutionary_government", capital="Ankara",
      removal=["no_confidence", "party_congress"],
      succession="Assembly government: the GNA elected each Commissar (Vekil) individually and the Speaker (Mustafa Kemal) chaired the Council of Executive Commissars; commissars could be voted out by the Assembly.",
      notes="Game: a rival state to the Istanbul sultanate during the War of Independence (1919-1922); Treaty of Lausanne 24 Jul 1923."),
